#include <WiFi.h>
#include <WebServer.h>
#include <DHT.h>

#define DHT_PIN 4
#define DHT_TYPE DHT11

const char* ssid = "KJKL";
const char* password = "102030405060708090";

DHT dht(DHT_PIN, DHT_TYPE);
WebServer server(80);

void handleRoot() {
  float humidity = dht.readHumidity();
  float temperature = dht.readTemperature();

  String html = R"rawliteral(
<!DOCTYPE html>
<html>
<head>
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Room Sensor</title>
  <style>
    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: flex;
      justify-content: center;
      align-items: center;
      background: #f5f5f7;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: #1d1d1f;
    }

    .container {
      width: min(500px, 90%);
    }

    h1 {
      font-size: 32px;
      margin-bottom: 24px;
    }

    .grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }

    .card {
      background: white;
      border-radius: 24px;
      padding: 24px;
      box-shadow: 0 8px 30px rgba(0,0,0,0.06);
    }

    .label {
      font-size: 14px;
      color: #86868b;
      margin-bottom: 10px;
    }

    .value {
      font-size: 42px;
      font-weight: 600;
      letter-spacing: -2px;
    }

    .status {
      margin-top: 16px;
      font-size: 13px;
      color: #86868b;
    }
  </style>
</head>

<body>
  <div class="container">
    <h1>Room</h1>

    <div class="grid">

      <div class="card">
        <div class="label">Temperature</div>
        <div class="value">
)rawliteral";

  if (isnan(temperature)) {
    html += "--";
  } else {
    html += String(temperature, 1);
    html += "°";
  }

  html += R"rawliteral(
        </div>
      </div>

      <div class="card">
        <div class="label">Humidity</div>
        <div class="value">
)rawliteral";

  if (isnan(humidity)) {
    html += "--";
  } else {
    html += String(humidity, 0);
    html += "%";
  }

  html += R"rawliteral(
        </div>
      </div>

    </div>

    <div class="status">
      ESP32 · DHT11
    </div>
  </div>
</body>
</html>
)rawliteral";

  server.send(200, "text/html", html);
}

void setup() {
  Serial.begin(115200);

  dht.begin();

  WiFi.begin(ssid, password);

  Serial.print("Connecting");

  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }

  Serial.println();
  Serial.println("Connected!");
  Serial.print("Open: http://");
  Serial.println(WiFi.localIP());

  server.on("/", handleRoot);
  server.begin();
}

void loop() {
  server.handleClient();
}
